const uint8_t *pk_text_cjk_ui_glyph(uint32_t code, uint8_t *width)
{
    for (size_t i = 0; i < sizeof(s_ui_codes) / sizeof(s_ui_codes[0]); ++i) {
        if (s_ui_codes[i] == code) {
            if (width) *width = s_ui_widths[i];
            return s_ui_bitmaps + s_ui_offsets[i];
        }
    }
    if (width) *width = 0;
    return NULL;
}
